import { MakeLogicType, actions, afterMount, kea, key, listeners, path, props, reducers } from 'kea'

import api from 'lib/api'

import { HogQLQuery, NodeKind } from '~/queries/schema/schema-general'

import { isExplicitEvaluationPass } from './utils'

export interface SessionEvaluation {
    evaluationId: string
    evaluationName: string
    verdict: boolean | null
    reasoning: string
    timestamp: string
}

export interface SessionEvaluationsLogicProps {
    sessionId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySessionEvaluationsLogicValues {
    sessionEvaluations: SessionEvaluation[]
    sessionEvaluationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySessionEvaluationsLogicActions {
    loadSessionEvaluations: () => {
        value: true
    }
    loadSessionEvaluationsFailure: () => {
        value: true
    }
    loadSessionEvaluationsSuccess: (evaluations: SessionEvaluation[]) => {
        evaluations: SessionEvaluation[]
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySessionEvaluationsLogicMeta {
    key: string
}

export type aiObservabilitySessionEvaluationsLogicType = MakeLogicType<
    aiObservabilitySessionEvaluationsLogicValues,
    aiObservabilitySessionEvaluationsLogicActions,
    SessionEvaluationsLogicProps,
    aiObservabilitySessionEvaluationsLogicMeta
>

export const aiObservabilitySessionEvaluationsLogic = kea<aiObservabilitySessionEvaluationsLogicType>([
    path(['scenes', 'ai-observability', 'aiObservabilitySessionEvaluationsLogic']),
    props({} as SessionEvaluationsLogicProps),
    key((props) => props.sessionId),

    actions({
        loadSessionEvaluations: true,
        loadSessionEvaluationsSuccess: (evaluations: SessionEvaluation[]) => ({ evaluations }),
        loadSessionEvaluationsFailure: true,
    }),

    reducers({
        sessionEvaluations: [
            [] as SessionEvaluation[],
            {
                loadSessionEvaluationsSuccess: (_, { evaluations }) => evaluations,
                loadSessionEvaluationsFailure: () => [],
            },
        ],
        sessionEvaluationsLoading: [
            false,
            {
                loadSessionEvaluations: () => true,
                loadSessionEvaluationsSuccess: () => false,
                loadSessionEvaluationsFailure: () => false,
            },
        ],
    }),

    listeners(({ actions, props }) => ({
        loadSessionEvaluations: async () => {
            const { sessionId } = props
            if (!sessionId) {
                actions.loadSessionEvaluationsFailure()
                return
            }

            // Session verdicts carry no $ai_trace_id, so SessionQueryRunner's `trace_id != ''`
            // filter drops them. They have to be read by $ai_session_id directly, the same way
            // aiObservabilitySessionFeedbackLogic reads $ai_metric session feedback.
            const evaluationsQuery: HogQLQuery = {
                kind: NodeKind.HogQLQuery,
                query: `
                    SELECT
                        properties.$ai_evaluation_id as evaluation_id,
                        properties.$ai_evaluation_name as evaluation_name,
                        properties.$ai_evaluation_result as verdict,
                        properties.$ai_evaluation_reasoning as reasoning,
                        timestamp
                    FROM events
                    WHERE event = '$ai_evaluation'
                      AND properties.$ai_target_type = 'session_id'
                      AND properties.$ai_session_id = {sessionId}
                    ORDER BY timestamp DESC
                `,
                values: { sessionId },
            }

            try {
                const response = await api.query(evaluationsQuery)
                const evaluations: SessionEvaluation[] = (response.results || []).map((row: any[]) => ({
                    evaluationId: row[0] || '',
                    evaluationName: row[1] || '',
                    verdict: row[2] === null || row[2] === undefined ? null : isExplicitEvaluationPass(row[2]),
                    reasoning: row[3] || '',
                    timestamp: row[4] || '',
                }))
                actions.loadSessionEvaluationsSuccess(evaluations)
            } catch (error) {
                console.error('Error loading session evaluations:', error)
                actions.loadSessionEvaluationsFailure()
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadSessionEvaluations()
    }),
])
